import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final nome=TextEditingController(),salario=TextEditingController(),percentual=TextEditingController();String resultado='';void calcular(){final s=double.tryParse(salario.text.replaceAll(',','.')),p=double.tryParse(percentual.text.replaceAll(',','.'));if(nome.text.trim().isEmpty||s==null||p==null){setState(()=>resultado='Preencha todos os campos corretamente.');return;}final aumento=s*p/100;setState(()=>resultado='Funcionário: ${nome.text}\nSalário atual: R\$ ${s.toStringAsFixed(2)}\nAumento: R\$ ${aumento.toStringAsFixed(2)}\nNovo salário: R\$ ${(s+aumento).toStringAsFixed(2)}');}void limpar(){nome.clear();salario.clear();percentual.clear();setState(()=>resultado='');}@override void dispose(){nome.dispose();salario.dispose();percentual.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Reajuste salarial')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:nome,decoration:const InputDecoration(labelText:'Funcionário')),TextField(controller:salario,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Salário atual')),TextField(controller:percentual,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Percentual de reajuste')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:calcular,child:const Text('Calcular')),const SizedBox(width:12),ElevatedButton(onPressed:limpar,child:const Text('Limpar'))]),const SizedBox(height:24),Text(resultado)])));}
